// Helper function to format date as YYYY-MM-DD in Riga timezone
function formatDate(date) {
  return date.toLocaleString('sv-SE', {
    timeZone: 'Europe/Riga',
    day: '2-digit',
    month: '2-digit',
    year: 'numeric',
  }).split(' ')[0];
}

// Get current date in Riga timezone
const now = new Date(new Date().toLocaleString('en-US', { timeZone: 'Europe/Riga' }));

// Find next Monday
const currentDay = now.getDay(); // 0 (Sun) to 6 (Sat)
const daysUntilNextMonday = ((8 - currentDay) % 7) || 7;
const nextMonday = new Date(now);
nextMonday.setDate(now.getDate() + daysUntilNextMonday);

// Next Friday after the found Monday
const nextFriday = new Date(nextMonday);
nextFriday.setDate(nextMonday.getDate() + 4);

return [{
  nextMon: formatDate(nextMonday),
  nextFri: formatDate(nextFriday)
}];
